    function testFuzz_property(uint256 amount, bool useReverter) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();
        Receiver okReceiver = new Receiver();

        address target = useReverter ? address(rev) : address(okReceiver);

        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

